<?php require_once __DIR__."/../config/auth.php";require_role(["admin","cashier"]);$ps=db()->query("SELECT id,sku,barcode,name_ar,name_en,sale_price,stock_qty FROM products WHERE is_active=1 AND stock_qty>0 ORDER BY name_en")->fetchAll();$cs=cash_session();include __DIR__."/partials/header.php";?><header><div><h1><?=t("نقطة البيع","Point of Sale")?></h1><p class="muted"><?=t("امسح Barcode / QR من جهاز السكانر لإضافة المنتج مباشرة","Scan a Barcode / QR to add the product instantly")?></p></div><div class="scanner-status" id="scannerStatus">● <?=t("السكانر جاهز","Scanner Ready")?></div></header><?php if(!$cs):?><div class="warn"><?=t("افتح جلسة كاشير من تقفيل اليوم أولاً.","Open a cashier session from Day Closing first.")?></div><?php endif;?><div class="pos"><section class="card"><div class="scanbar"><span>⌕</span><input id="search" class="search" autocomplete="off" autofocus placeholder="<?=t("امسح Barcode / QR أو اكتب اسم المنتج / SKU","Scan Barcode / QR or type product name / SKU")?>"><button id="clearSearch" class="btn" type="button">×</button></div><div class="scan-hint"><?=t("السكانر يتعامل مثل الكيبورد: Scan ثم Enter، والمنتج يضاف تلقائياً.","Scanner works like a keyboard: Scan then Enter, and the item is added automatically.")?></div><div class="products"><?php foreach($ps as $p):?><button class="product" data-id="<?=$p["id"]?>" data-name="<?=e($p["name_en"]?:$p["name_ar"])?>" data-price="<?=$p["sale_price"]?>" data-stock="<?=$p["stock_qty"]?>" data-barcode="<?=e($p["barcode"])?>" data-sku="<?=e($p["sku"])?>"><b><?=e(lang()==="ar"?$p["name_ar"]:$p["name_en"])?></b><small><?=e($p["sku"])?><br><?=e($p["barcode"])?></small><strong><?=number_format($p["sale_price"],2)?> EGP</strong><span><?=t("المخزون","Stock")?> <?=$p["stock_qty"]?></span></button><?php endforeach;?></div></section><section class="card checkout"><div class="checkout-head"><h2><?=t("الفاتورة الحالية","Current Sale")?></h2><span id="itemCount">0 <?=t("صنف","items")?></span></div><div class="cart-list"><table id="cart"><thead><tr><th><?=t("الصنف","Item")?></th><th><?=t("الكمية","Qty")?></th><th><?=t("الإجمالي","Total")?></th><th></th></tr></thead><tbody></tbody></table></div><label><?=t("الخصم","Discount")?><input id="discount" type="number" min="0" step=".01" value="0"></label><label><?=t("طريقة الدفع","Payment")?><select id="payment"><option value="cash"><?=t("نقدي","Cash")?></option><option value="card"><?=t("بطاقة","Card")?></option><option value="other"><?=t("أخرى","Other")?></option></select></label><label><?=t("المدفوع","Paid")?><input id="paid" type="number" min="0" step=".01" value="0"></label><div class="totals"><div><span><?=t("الإجمالي","Total")?></span><strong id="total">0.00 EGP</strong></div><div><span><?=t("الباقي","Change")?></span><strong id="change">0.00 EGP</strong></div></div><button id="sell" class="btn primary full" <?=!$cs?"disabled":""?>>🧾 <?=t("إتمام البيع وطباعة الريست","Complete Sale & Print Receipt")?></button></section></div><script>window.CSRF="<?=e(csrf())?>";</script><script src="assets/pos.js"></script><?php include __DIR__."/partials/footer.php";?>
